class Location(BaseModel):
    """
    Where a work is hosted
    """

    is_oa: bool | None = Field(
        None, description='Whether this location provides open access'
    )
    landing_page_url: str | None = Field(None, description='URL to the landing page')
    pdf_url: str | None = Field(None, description='Direct URL to PDF')
    source: DehydratedSource | None = Field(
        None,
        description='[Dehydrated source](/api-reference/sources#the-dehydratedsource-object)',
    )
    license: str | None = Field(
        None, description='The [license](/api-reference/licenses) (e.g., cc-by)'
    )
    license_id: str | None = None
    version: Version | None = Field(
        None, description='Version of the work at this location'
    )
    is_accepted: bool | None = None
    is_published: bool | None = None


class Authorship(BaseModel):
    """
    Author and their affiliation for a work
    """

    author_position: AuthorPosition | None = Field(
        None, description='Position in author list'
    )
    author: DehydratedAuthor | None = Field(
        None,
        description='[Dehydrated author](/api-reference/authors#the-dehydratedauthor-object)',
    )
    institutions: list[DehydratedInstitution] | None = Field(
        None,
        description='[Dehydrated institutions](/api-reference/institutions#the-dehydratedinstitution-object)',
    )
    countries: list[str] | None = Field(
        None, description='Country codes of affiliations'
    )
    is_corresponding: bool | None = Field(
        None, description='Whether this is the corresponding author'
    )
    raw_author_name: str | None = Field(
        None, description='Author name as it appears in the work'
    )
    raw_affiliation_strings: list[str] | None = None


class Affiliation(BaseModel):
    institution: DehydratedInstitution | None = Field(
        None,
        description='[Dehydrated institution](/api-reference/institutions#the-dehydratedinstitution-object)',
    )
    years: list[int] | None = None


class Author(BaseModel):
    """
    A person who creates scholarly works
    """

    id: str | None = Field(
        None,
        description='The OpenAlex ID for this author.',
        examples=['https://openalex.org/A5023888391'],
    )
    orcid: str | None = Field(
        None,
        description='The ORCID ID for this author. This is the Canonical External ID for authors.',
    )
    display_name: str | None = Field(
        None, description='The name of the author as a single string.'
    )
    display_name_alternatives: list[str] | None = Field(
        None, description="Other ways this author's name has been displayed."
    )
    longest_name: str | None = Field(
        None,
        description='The longest name variant found for this author across all their works.',
    )
    parsed_longest_name: ParsedLongestName | None = Field(
        None, description='The longest name parsed into its component parts.'
    )
    works_count: int | None = Field(
        None, description='The number of works this author has created.'
    )
    cited_by_count: int | None = Field(
        None,
        description='The total number of works that cite a work this author has created.',
    )
    summary_stats: SummaryStats | None = Field(None, description='Citation metrics:')
    affiliations: list[Affiliation] | None = Field(
        None,
        description='List of affiliations this author has claimed in their publications. Each object has:',
    )
    last_known_institutions: list[DehydratedInstitution] | None = Field(
        None,
        description="This author's last known institutional affiliations. Each item is a dehydrated Institution object.",
    )
    topics: list[Topic] | None = None
    counts_by_year: list[CountsByYearItem1] | None = Field(
        None,
        description='`works_count` and `cited_by_count` for each of the last ten years.',
    )
    ids: Ids1 | None = Field(None, description='External identifiers:')
    works_api_url: str | None = Field(
        None, description="A URL that will get you a list of all this author's works."
    )
    created_date: date_aliased | None = Field(
        None, description='When this author was added to OpenAlex (ISO 8601 date).'
    )
    updated_date: datetime | None = Field(
        None, description='When this author was last updated (ISO 8601 datetime).'
    )


class AuthorsListResponse(BaseModel):
    meta: Meta | None = None
    results: list[Author] | None = None
    group_by: list[GroupByResult] | None = None


class Work(BaseModel):
    """
    A scholarly document (article, book, dataset, thesis, etc.)
    """

    id: str | None = Field(
        None,
        description='The OpenAlex ID for this work.',
        examples=['https://openalex.org/W2741809807'],
    )
    doi: str | None = Field(
        None,
        description='The DOI for the work. This is the Canonical External ID for works.',
        examples=['https://doi.org/10.7717/peerj.4375'],
    )
    title: str | None = Field(None, description='The title of this work.')
    display_name: str | None = Field(
        None,
        description='Same as `title`. Included for consistency with other entities.',
    )
    publication_year: int | None = Field(
        None, description='The year this work was published.'
    )
    publication_date: date_aliased | None = Field(
        None, description='The day when this work was published (ISO 8601 format).'
    )
    type: str | None = Field(
        None,
        description='The type of the work. Common values: `article`, `book`, `dataset`, `preprint`, `dissertation`, `book-chapter`.',
    )
    language: str | None = Field(
        None, description='[Language](/api-reference/languages) in ISO 639-1 format'
    )
    cited_by_count: int | None = Field(
        None, description='The number of citations to this work.'
    )
    is_retracted: bool | None = Field(
        None,
        description='True if this work has been retracted (from Retraction Watch database).',
    )
    is_paratext: bool | None = Field(
        None,
        description='True if this work is paratext (e.g., front cover, table of contents).',
    )
    primary_location: Location | None = Field(
        None,
        description='A Location object with the primary location of this work (closest to the version of record). Includes `source`, `landing_page_url`, `pdf_url`, `is_oa`, `license`, and `version`.',
    )
    locations: list[Location] | None = Field(
        None,
        description='List of Location objects describing all unique places where this work lives.',
    )
    best_oa_location: Location | None = Field(
        None,
        description='A Location object with the best available open access location for this work.',
    )
    open_access: OpenAccess | None = Field(
        None, description='Information about the access status of this work:'
    )
    authorships: list[Authorship] | None = Field(
        None,
        description='List of Authorship objects representing authors and their institutions. Limited to the first 100 authors. Each authorship includes `author`, `institutions`, `author_position`, `is_corresponding`, and other fields.',
    )
    ids: Ids | None = Field(
        None,
        description='External identifiers: `openalex`, `doi`, `mag`, `pmid`, `pmcid`.',
    )
    biblio: Biblio | None = Field(
        None,
        description='Bibliographic info: `volume`, `issue`, `first_page`, `last_page`.',
    )
    abstract_inverted_index: dict[str, Any] | None = Field(
        None,
        description="The abstract as an inverted index (word positions). OpenAlex doesn't include plaintext abstracts due to legal constraints. Use the `has_abstract` filter to get works with or without abstracts.",
    )
    referenced_works: list[str] | None = Field(
        None, description='OpenAlex IDs for works that this work cites.'
    )
    referenced_works_count: int | None = Field(
        None, description='The number of works that this work cites.'
    )
    related_works: list[str] | None = Field(
        None,
        description='OpenAlex IDs for works related to this work (computed algorithmically).',
    )
    topics: list[WorkTopic] | None = Field(
        None,
        description='List of up to 3 Topics for this work, each with a relevance score.',
    )
    primary_topic: WorkTopic | None = Field(
        None,
        description='The top ranked Topic for this work, with `id`, `display_name`, `score`, and hierarchy (`subfield`, `field`, `domain`).',
    )
    keywords: list[WorkKeyword] | None = Field(
        None,
        description="Keywords identified based on the work's topics, with relevance scores.",
    )
    funders: list[DehydratedFunder] | None = Field(
        None,
        description='Dehydrated Funder objects representing the funders of this work.',
    )
    awards: list[Award] | None = Field(
        None,
        description='Dehydrated Award objects representing grants associated with this work.',
    )
    fwci: float | None = Field(
        None,
        description='Field-weighted Citation Impact, calculated as citations received / citations expected.',
    )
    citation_normalized_percentile: CitationNormalizedPercentile | None = Field(
        None,
        description='Percentile of citation count normalized by work type, year, and subfield. Includes `value`, `is_in_top_1_percent`, `is_in_top_10_percent`.',
    )
    cited_by_percentile_year: CitedByPercentileYear | None = Field(
        None,
        description='Percentile rank compared to other works published in the same year. Contains `min` and `max`.',
    )
    counts_by_year: list[CountsByYearItem] | None = Field(
        None, description='`cited_by_count` for each of the last ten years.'
    )
    sustainable_development_goals: list[SustainableDevelopmentGoal] | None = Field(
        None,
        description="UN Sustainable Development Goals the work addresses, from OpenAlex's own classifier (since October 2026). A goal is listed when its score is 0.4 or above; score is the classifier's confidence from 0 to 1, not a probability.",
    )
    sustainable_development_goals_aurora: (
        list[SustainableDevelopmentGoalsAuroraItem] | None
    ) = Field(None, deprecated=True, description='Aurora SDG-BERT tags as of October 2026; deprecated, removed in November 2026; use sustainable_development_goals. Output only: no filter, sort or group_by.')
    mesh: list[MeshItem] | None = Field(
        None, description='MeSH tags for works found in PubMed.'
    )
    indexed_in: list[str] | None = Field(
        None,
        description='Sources this work is indexed in. Values: `arxiv`, `crossref`, `doaj`, `pubmed`.',
    )
    has_content: HasContent | None = Field(
        None, description='Information about downloadable full-text content:'
    )
    content_url: str | None = Field(
        None,
        description='URL for downloading full-text content. Only present when `has_content.pdf` or `has_content.grobid_xml` is true.',
    )
    created_date: date_aliased | None = Field(
        None, description='When this work was added to OpenAlex (ISO 8601 date).'
    )
    updated_date: datetime | None = Field(
        None, description='When this work was last updated (ISO 8601 datetime).'
    )


class WorksListResponse(BaseModel):
    meta: Meta | None = None
    results: list[Work] | None = None
    group_by: list[GroupByResult] | None = None
